-- ===================== RUMScript_UI.lua =====================
-- Shared UI module for the RUM Script hub. Hosted externally (e.g. GitHub raw)
-- and referenced from the admin "Link UI dùng chung" field for this script,
-- with "Tự động nạp UI" enabled on the logic script. The site then auto-inserts
--   local UI = loadstring(game:HttpGet("<this file's URL>"))()
-- at the top of the logic script, so `UI` below is what that line receives.
--
-- This file only BUILDS the UI when UI.Init(env) is called — loading this
-- module by itself does nothing yet, because at load time the logic script's
-- settings/capability/callbacks don't exist. The logic script calls
-- UI.Init(env) once, near the end of its own file, after everything else
-- (settings, capability, all apply* functions, named profiles) is ready.
--
-- `env` is a plain table of everything this module needs from the logic
-- script: Roblox service handles, the settings/defaults/capability tables,
-- and functions (status/log/guarded/queueSave/writeSettings/makeReport/
-- setOption/apply*/restoreCollisions/restoreEffects/disarmRuntime/
-- decodeBase64/the named-profile functions), plus `runtimeState`, a small
-- shared table for the handful of primitives (alive, saveRevision,
-- pauseAfterDelete, idleConnection, noclipConnection, idleNotice) that BOTH
-- files read and write — two separate loadstring chunks don't share plain
-- local-variable storage, so those live in a table passed by reference
-- instead of as bare locals.
--
-- Below this header: a few embedded image assets (logo/icons/dots/chibi/leaf,
-- as base64 PNG data), then the UI module table and its Init function, whose
-- body is the original native UI code (visual style, FX engine, Home/Player/
-- Settings pages, compact layout, window boot) unchanged except for the env
-- extraction at the very top of Init.
