local UIModule = {}

function UIModule.Init(env)
	-- ===== env extraction: everything below this point is the original =====
	-- ===== native UI code, unchanged, now reading these as upvalues. =====
	local CONFIG = env.CONFIG
	local settings = env.settings
	local defaults = env.defaults
	local capability = env.capability
	local player = env.player
	local HttpService = env.HttpService
	local UserInputService = env.UserInputService
	local RunService = env.RunService
	local TweenService = env.TweenService
	local TeleportService = env.TeleportService
	local runtimeState = env.runtimeState

	local status = env.status
	local log = env.log
	local guarded = env.guarded
	local queueSave = env.queueSave
	local writeSettings = env.writeSettings
	local makeReport = env.makeReport
	local setOption = env.setOption

	local applyNoclip = env.applyNoclip
	local applyAntiAFK = env.applyAntiAFK
	local applyMovement = env.applyMovement
	local applyGraphics = env.applyGraphics
	local applyAutoReconnect = env.applyAutoReconnect
	local applyAutoExecute = env.applyAutoExecute
	local restoreCollisions = env.restoreCollisions
	local restoreEffects = env.restoreEffects
	local disarmRuntime = env.disarmRuntime

	local globalEnv = env.globalEnv
	local decodeBase64 = env.decodeBase64

	local saveConfigSlot = env.saveConfigSlot
	local loadConfigSlot = env.loadConfigSlot
	local deleteConfigSlot = env.deleteConfigSlot
	local listConfigSlots = env.listConfigSlots
	local getAutoloadSlot = env.getAutoloadSlot
	local setAutoloadSlot = env.setAutoloadSlot

	-- RUM Script native UI redesign (internal review candidate)
	-- Uses real Roblox UI elements. Logo, mascot and sidebar artwork are separate images.
	-- No full-screen screenshot is used as a substitute for UI.
	local W, H = 1296, 730
	local T = {
	 -- TRUE BLACK / NEUTRAL GRAYS: no green tint in structural surfaces.
	 bg=Color3.fromRGB(0,0,0), panel=Color3.fromRGB(11,11,11),
	 panel2=Color3.fromRGB(21,21,21), primary=Color3.fromRGB(121,255,38),
	 glow=Color3.fromRGB(78,235,28), deep=Color3.fromRGB(13,13,13),
	 muted=Color3.fromRGB(204,204,204), white=Color3.fromRGB(250,250,250),
	 off=Color3.fromRGB(49,49,49), danger=Color3.fromRGB(238,124,117)
	}
	local UI = {}
	local FX = {} -- V8 motion / tech visual layer (client-side cosmetics only)
	FX.lite = (CONFIG.FX_MODE == 'Lite')
	FX.gridHosts = {}
	local readableLabels = setmetatable({}, {__mode='k'})
	local compactCopies = setmetatable({}, {__mode='k'})
	-- Short, meaningful labels for small viewports. Avoid clipping full sentences.
	-- The approved text remains intact on normal/wide screens.
	local compactText = {
	 ['Roblox Script Hub']='Script Hub',
	 ['Your modern script hub for Roblox']='Roblox Script Hub',
	 ['Notifications']='Alerts',
	 ['A clean, modern, and powerful script hub']='Modern Roblox scripts',
	 ['for your Roblox experience.']='for Roblox.',
	 ['Future features will appear here.']='Modules will appear here.',
	 ['Basic preferences']='Preferences',
	 ['Character controls · values may be limited by the game']='Character controls',
	 ['Performance, connection and configuration']='Settings & connection',
	 ['Adjust character movement']='Movement controls',
	 ['Collision control (client-dependent)']='Collision settings',
	 ['Idle handling (client-dependent)']='Idle settings',
	 ['Client-side visual preferences']='Visual preferences',
	 ['Availability depends on the client']='Client-dependent',
	 ['Reduce selected visual effects']='Reduce visual effects',
	 ['Managed by the client, not this hub']='Controlled by client',
	 ['Unavailable after a full disconnect']='Unavailable offline',
	 ['Cannot guarantee idle disconnect prevention']='Not guaranteed',
	 ['May be overridden by the game']='Game may override',
	}
	local function applyTextReadability(scale)
	 if not scale or scale<=0 then return end
	 for label, original in pairs(readableLabels) do
	  if label and label.Parent then
	   -- Actual on-screen reading size never drops below ~11 px for labels.
	   -- Caps avoid expanding small captions into titles.
	   local physicalFloor = original < 24 and 12 or 13
	   label.TextSize = math.min(original*1.7, math.max(original, math.ceil(physicalFloor/scale)))
	   local copy=compactCopies[label]
	   if copy then label.Text = scale < .65 and copy.compact or copy.original end
	  end
	 end
	end
	local navHandlers = {}
	local pageHandlers = {}
	local aliveUI=true
	local main, content, shell, root, scaling, mini, toastText, toastBox
	local compactToast, compactToastText
	-- Include a LIVE visible-text clipping check in the built-in Debug report.
	-- This is a read-only UI audit, not a claim that the game/runtime works.
	local previousReport = makeReport
	local function visibleTextAudit()
	 if not root or not root.Parent then return 'UI text audit: no visible root' end
	 local inspected,clipped=0,0
	 local samples={}
	 for _,node in ipairs(root:GetDescendants())do
	  if node:IsA('TextLabel') and type(node.Text)=='string' and node.Text~='' then
	   local visible=true
	   local ancestor=node
	   while ancestor and ancestor~=root do
	    if ancestor:IsA('GuiObject') and ancestor.Visible==false then visible=false;break end
	    ancestor=ancestor.Parent
	   end
	   if visible then
	    local ok,w,t=pcall(function()return node.AbsoluteSize.X,node.TextBounds.X end)
	    if ok and type(w)=='number' and type(t)=='number' and w>0 then
	     inspected+=1
	     if not node.TextWrapped and t>w+3 then
	      clipped+=1
	      if #samples<5 then table.insert(samples,node.Text:sub(1,48)) end
	     end
	    end
	   end
	  end
	 end
	 local line='Visible label audit: '..inspected..' measured; '..clipped..' possible truncations'
	 if #samples>0 then line=line..' ['..table.concat(samples,' / ')..']' end
	 return line
	end
	makeReport=function()
	 return previousReport()..'\n\nUI READABILITY\n'..visibleTextAudit()
	end
	local function closeNative()
	 aliveUI=false
	 runtimeState.alive=false -- stop deferred saves and periodic client-side checks from the previous instance
	 runtimeState.saveRevision+=1
	 for _,c in ipairs(navHandlers) do pcall(function() c:Disconnect() end) end
	 for _,c in ipairs(pageHandlers) do pcall(function() c:Disconnect() end) end
	 for _,c in ipairs(allConnections) do pcall(function() c:Disconnect() end) end
	 if runtimeState.noclipConnection then pcall(function() runtimeState.noclipConnection:Disconnect() end);runtimeState.noclipConnection=nil end
	 if runtimeState.idleConnection then pcall(function() runtimeState.idleConnection:Disconnect() end);runtimeState.idleConnection=nil end
	 pcall(disarmRuntime)
	 pcall(restoreCollisions)
	 pcall(restoreEffects)
	 if root and root.Parent then root:Destroy() end
	 globalEnv.RUMScriptNative_Close=nil
	end
	local currentPage='Home'
	local dynamicControls = {}
	local dialog
	local screenshotVersion='hub-v8-fx-motion-neon-telemetry'
	-- Forward references: desktop controls are created before compact UI functions.
	local setMinimized, toggleWindowSize, refreshWindowScale
	
	local function obj(kind,parent,props)
	 local it=Instance.new(kind)
	 for k,v in pairs(props or {}) do it[k]=v end
	 it.Parent=parent
	 return it
	end
	local function pos(x,y,w,h) return UDim2.fromOffset(x,y),UDim2.fromOffset(w,h) end
	local function round(it,n) obj('UICorner',it,{CornerRadius=UDim.new(0,n or 10)});return it end
	local function edge(it,c,n,trans)
	 obj('UIStroke',it,{Color=c or T.primary,Thickness=n or 1,Transparency=trans or 0,ApplyStrokeMode=Enum.ApplyStrokeMode.Border})
	 return it
	end
	local function frame(parent,x,y,w,h,color,z,r)
	 local p,s=pos(x,y,w,h)
	 local it=obj('Frame',parent,{Position=p,Size=s,BackgroundColor3=color or T.panel,
	  BorderSizePixel=0,ZIndex=z or 5})
	 if r then round(it,r) end
	 return it
	end
	local function text(parent,str,x,y,w,h,size,color,bold,z,align)
	 local p,s=pos(x,y,w,h)
	 local target=obj('TextLabel',parent,{Position=p,Size=s,BackgroundTransparency=1,
	 Text=tostring(str),Font=bold and Enum.Font.GothamBold or Enum.Font.Gotham,
	 TextColor3=color or T.white,TextSize=size or 21,TextXAlignment=align or Enum.TextXAlignment.Left,
	 TextYAlignment=Enum.TextYAlignment.Center,ZIndex=z or 20,TextTruncate=Enum.TextTruncate.AtEnd})
	 readableLabels[target]=size or 21
	 if compactText[str] then compactCopies[target]={original=str,compact=compactText[str]} end
	 if UI.fit then applyTextReadability(UI.fit) end
	 return target
	end
	local function grad(it,a,b,rot)
	 obj('UIGradient',it,{Color=ColorSequence.new(a,b),Rotation=rot or 90})
	end
	
	-- =====================================================================
	-- RUM FX ENGINE V8 · motion, neon, scanlines, boot sequence, telemetry
	-- Purely visual. Every tween is pcall-guarded so one bad property never
	-- breaks the hub. All loops stop when the UI closes (aliveUI=false).
	-- =====================================================================
	local function tw(o,t,props,style,dir,delay)
	 if not o or not o.Parent then return nil end
	 local ok,tween=pcall(function()
	  return TweenService:Create(o,TweenInfo.new(t,style or Enum.EasingStyle.Quint,
	   dir or Enum.EasingDirection.Out,0,false,delay or 0),props)
	 end)
	 if ok and tween then tween:Play();return tween end
	 return nil
	end
	FX.tw=tw
	FX.spinners=setmetatable({},{__mode='k'})
	FX.pulses=setmetatable({},{__mode='k'})
	FX.orbits=setmetatable({},{__mode='k'})
	function FX.spin(g,speed) if g then FX.spinners[g]=speed or 90 end;return g end
	function FX.pulse(o,prop,a,b,period) if o then FX.pulses[o]={prop,a,b,period or 2} end;return o end
	function FX.strokeOf(it) return it and it:FindFirstChildOfClass('UIStroke') end
	local fxClock=0
	function FX.startLoop()
	 local acc=0
	 connect(RunService.Heartbeat,function(dt)
	  if not aliveUI or FX.lite then return end
	  -- Throttle cosmetic updates to ~30 Hz; nobody sees the difference, low-end CPUs do.
	  acc+=dt
	  if acc<1/30 then return end
	  dt=acc;acc=0
	  fxClock+=dt
	  for g,speed in pairs(FX.spinners) do
	   if g.Parent then g.Rotation=(g.Rotation+speed*dt)%360 else FX.spinners[g]=nil end
	  end
	  for o,p in pairs(FX.pulses) do
	   if o.Parent then
	    local k=(math.sin(fxClock*math.pi*2/p[4])+1)*.5
	    pcall(function() o[p[1]]=p[2]+(p[3]-p[2])*k end)
	   else FX.pulses[o]=nil end
	  end
	  for d,o in pairs(FX.orbits) do
	   if d.Parent then
	    local a=fxClock*o.speed+o.phase
	    d.Position=UDim2.fromOffset(20.5+math.cos(a)*o.rx-o.size/2,20.5+math.sin(a)*o.ry-o.size/2)
	   else FX.orbits[d]=nil end
	  end
	 end,navHandlers)
	end
	-- Travelling light along a border: white base colour + rotating lime gradient.
	function FX.neonStroke(stroke,speed)
	 if not stroke then return nil end
	 stroke.Color=Color3.new(1,1,1)
	 local g=obj('UIGradient',stroke,{Color=ColorSequence.new({
	  ColorSequenceKeypoint.new(0,Color3.fromRGB(121,255,38)),
	  ColorSequenceKeypoint.new(.32,Color3.fromRGB(48,140,14)),
	  ColorSequenceKeypoint.new(.5,Color3.fromRGB(232,255,214)),
	  ColorSequenceKeypoint.new(.68,Color3.fromRGB(48,140,14)),
	  ColorSequenceKeypoint.new(1,Color3.fromRGB(121,255,38))})})
	 return FX.spin(g,speed or 70)
	end
	-- Half-arc spinning ring (radar / loader look).
	function FX.ring(parent,x,y,size,z,thick,speed)
	 local r=frame(parent,x,y,size,size,T.bg,z or 9,math.ceil(size/2))
	 r.BackgroundTransparency=1;r.Active=false
	 local s=obj('UIStroke',r,{Color=Color3.new(1,1,1),Thickness=thick or 2,Transparency=0})
	 local g=obj('UIGradient',s,{
	  Color=ColorSequence.new(T.primary,Color3.fromRGB(225,255,200)),
	  Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,0),NumberSequenceKeypoint.new(.48,.1),
	   NumberSequenceKeypoint.new(.5,1),NumberSequenceKeypoint.new(1,1)})})
	 FX.spin(g,speed or 140)
	 return r,s
	end
	-- HUD targeting brackets just outside each corner of a rect.
	function FX.brackets(parent,x,y,w,h,len,thick,z,inset)
	 local list={}
	 local function bar(px,py,pw,ph)
	  local b=frame(parent,px,py,pw,ph,T.primary,z,0);b.Active=false
	  FX.pulse(b,'BackgroundTransparency',.05,.6,2.8)
	  table.insert(list,b)
	 end
	 local i,L,t=inset,len,thick
	 bar(x+i,y+i,L,t);bar(x+i,y+i,t,L)
	 bar(x+w-i-L,y+i,L,t);bar(x+w-i-t,y+i,t,L)
	 bar(x+i,y+h-i-t,L,t);bar(x+i,y+h-i-L,t,L)
	 bar(x+w-i-L,y+h-i-t,L,t);bar(x+w-i-t,y+h-i-L,t,L)
	 return list
	end
	-- Faint tech grid that sits behind the cards.
	function FX.grid(parent,x,y,w,h,step,z)
	 local host=frame(parent,x,y,w,h,T.bg,z,0)
	 host.BackgroundTransparency=1;host.ClipsDescendants=true;host.Active=false
	 table.insert(FX.gridHosts,host)
	 if FX.lite then return host end
	 local fade=NumberSequence.new({NumberSequenceKeypoint.new(0,1),NumberSequenceKeypoint.new(.25,0),
	  NumberSequenceKeypoint.new(.75,0),NumberSequenceKeypoint.new(1,1)})
	 for gx=step,w-1,step do
	  local l=frame(host,gx,0,1,h,T.primary,z,0);l.BackgroundTransparency=.93
	  obj('UIGradient',l,{Rotation=90,Transparency=fade})
	 end
	 for gy=step,h-1,step do
	  local l=frame(host,0,gy,w,1,T.primary,z,0);l.BackgroundTransparency=.93
	  obj('UIGradient',l,{Rotation=0,Transparency=fade})
	 end
	 return host
	end
	function FX.veil(parent,x,y,w,h,r,z)
	 local v=frame(parent,x,y,w,h,T.bg,z,r)
	 v.BackgroundTransparency=1;v.Visible=false;v.Active=false
	 return v
	end
	function FX.mono(parent,str,x,y,w,h,size,color,z,align)
	 local p,s=pos(x,y,w,h)
	 return obj('TextLabel',parent,{Position=p,Size=s,BackgroundTransparency=1,Text=str,
	  Font=Enum.Font.Code,TextSize=size,TextColor3=color or T.white,
	  TextXAlignment=align or Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Center,
	  ZIndex=z or 20,TextTruncate=Enum.TextTruncate.AtEnd})
	end
	-- Typewriter reveal without touching .Text (compact text swaps stay intact).
	function FX.typewrite(label,dur,delay)
	 if not label or FX.lite then return end
	 local total=utf8.len(label.ContentText) or #label.ContentText
	 if total<=0 then return end
	 label.MaxVisibleGraphemes=0
	 task.spawn(function()
	  if delay then task.wait(delay) end
	  local t0=os.clock();local d=dur or .45
	  while aliveUI and label.Parent do
	   local k=math.clamp((os.clock()-t0)/d,0,1)
	   label.MaxVisibleGraphemes=math.floor(total*k+.5)
	   if k>=1 then break end
	   RunService.Heartbeat:Wait()
	  end
	  if label.Parent then label.MaxVisibleGraphemes=-1 end
	 end)
	end
	-- Decrypt / glitch text reveal for short ASCII titles.
	local GLYPHS='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#$%&@<>/=+'
	function FX.decode(label,final,dur)
	 if not label then return end
	 final=final or label.Text
	 if FX.lite then label.Text=final;return end
	 task.spawn(function()
	  local t0=os.clock();local d=dur or .4;local n=#final
	  while aliveUI and label.Parent do
	   local k=math.clamp((os.clock()-t0)/d,0,1)
	   local shown=math.floor(n*k)
	   local out=final:sub(1,shown)
	   for i=shown+1,n do
	    if final:sub(i,i)==' ' then out..=' ' else
	     local r=math.random(1,#GLYPHS);out..=GLYPHS:sub(r,r) end
	   end
	   label.Text=out
	   if k>=1 then break end
	   task.wait(.035)
	  end
	  if label.Parent then label.Text=final end
	 end)
	end
	-- Cards rise into place one after another.
	function FX.pageIn(container,veil)
	 if not container or not container.Parent or FX.lite then return end
	 if veil then
	  veil.Visible=true;veil.BackgroundTransparency=.1
	  tw(veil,.34,{BackgroundTransparency=1},Enum.EasingStyle.Quad)
	  task.delay(.36,function() if veil.Parent and veil.BackgroundTransparency>.98 then veil.Visible=false end end)
	 end
	 local i=0
	 for _,child in ipairs(container:GetChildren()) do
	  if child:IsA('GuiObject') then
	   local p=child.Position
	   child.Position=p+UDim2.fromOffset(0,16)
	   tw(child,.45,{Position=p},Enum.EasingStyle.Quint,Enum.EasingDirection.Out,math.min(i,12)*.022)
	   i+=1
	  end
	 end
	end
	function FX.fadeOut(rootFrame,t)
	 local list=rootFrame:GetDescendants()
	 table.insert(list,rootFrame)
	 for _,d in ipairs(list) do
	  if d:IsA('GuiObject') then tw(d,t,{BackgroundTransparency=1},Enum.EasingStyle.Quad) end
	  if d:IsA('TextLabel') then tw(d,t,{TextTransparency=1},Enum.EasingStyle.Quad) end
	  if d:IsA('ImageLabel') then tw(d,t,{ImageTransparency=1},Enum.EasingStyle.Quad) end
	  if d:IsA('UIStroke') then tw(d,t,{Transparency=1},Enum.EasingStyle.Quad) end
	 end
	end
	function FX.flash(fx)
	 if not fx or not fx.chrome then return end
	 local base=fx.chromeThick or 2
	 tw(fx.chrome,.12,{Thickness=base+3.5},Enum.EasingStyle.Quad)
	 task.delay(.13,function() tw(fx.chrome,.5,{Thickness=base},Enum.EasingStyle.Quad) end)
	end
	-- Live FPS / network readout. Values are measured, not invented.
	function FX.hud(parent,x,y,w,h,compact,z)
	 local box=frame(parent,x,y,w,h,Color3.fromRGB(7,7,7),z,compact and 8 or 12)
	 edge(box,Color3.fromRGB(72,72,72),1,.15)
	 local dot=frame(box,compact and 7 or 14,compact and 6 or 15,compact and 5 or 8,compact and 5 or 8,T.primary,z+2,4)
	 FX.pulse(dot,'BackgroundTransparency',0,.75,1.3)
	 FX.mono(box,compact and 'LIVE' or 'SYSTEM ONLINE',compact and 16 or 30,compact and 1 or 8,
	  w-40,compact and 14 or 22,compact and 9 or 13,T.primary,z+2)
	 local fps=FX.mono(box,'FPS --',compact and 7 or 14,compact and 14 or 34,compact and 46 or 92,
	  compact and 13 or 20,compact and 10 or 14,T.white,z+2)
	 local ping=FX.mono(box,'NET --',compact and 52 or 106,compact and 14 or 34,compact and 48 or 98,
	  compact and 13 or 20,compact and 10 or 14,T.muted,z+2)
	 local count=compact and 12 or 24
	 local base=compact and h-5 or h-10
	 local bars={}
	 for i=1,count do
	  local b=frame(box,(compact and 7 or 14)+(i-1)*7,base-2,5,2,T.primary,z+2,1)
	  b.BackgroundTransparency=.8
	  bars[i]=b
	 end
	 return {fps=fps,ping=ping,bars=bars,base=base,max=compact and 11 or 26}
	end
	-- Drop every continuous effect: grid, spinning rings, pulses, text/page animation.
	function FX.setLite(reason)
	 if FX.lite then return end
	 FX.lite=true
	 for _,h in ipairs(FX.gridHosts) do if h.Parent then h:Destroy() end end
	 table.clear(FX.gridHosts)
	 status('FX','Lite mode: '..tostring(reason))
	 if UI.notify then UI.notify('Low FPS detected: Lite FX enabled') end
	end
	function FX.startTelemetry()
	 local frames,acc=0,0
	 local lowCount=0
	 local history={}
	 connect(RunService.Heartbeat,function(dt)
	  if not aliveUI then return end
	  frames+=1;acc+=dt
	  if acc<.5 then return end
	  local fps=math.floor(frames/acc+.5);frames,acc=0,0
	  local net='--'
	  local ok,p=pcall(function() return player:GetNetworkPing() end)
	  if ok and type(p)=='number' then net=tostring(math.floor(p*1000+.5))..'ms' end
	  table.insert(history,fps);if #history>24 then table.remove(history,1) end
	  -- Auto mode: ~2s under 28 FPS switches to Lite automatically.
	  if CONFIG.FX_MODE=='Auto' and not FX.lite then
	   lowCount=fps<28 and lowCount+1 or 0
	   if lowCount>=4 then FX.setLite('auto, '..fps..' FPS') end
	  end
	  for _,h in ipairs({UI.hud,UI.cHud}) do
	   if h and h.fps.Parent then
	    h.fps.Text='FPS '..fps
	    h.ping.Text='NET '..net
	    h.fps.TextColor3=fps>=50 and T.primary or (fps>=30 and Color3.fromRGB(255,214,64) or T.danger)
	    local n=#h.bars
	    for i=1,n do
	     local v=history[#history-n+i]
	     local bh=v and math.clamp(math.floor(math.min(v,120)/120*h.max+.5),2,h.max) or 2
	     local b=h.bars[i]
	     b.Size=UDim2.fromOffset(5,bh)
	     b.Position=UDim2.fromOffset(b.Position.X.Offset,h.base-bh)
	     b.BackgroundTransparency=v and (i==n and 0 or .3) or .8
	    end
	   end
	  end
	 end,navHandlers)
	end
	local function panel(parent,x,y,w,h,r)
	 -- Native UI. One subtle outer contour + a clean body outline.
	 -- Avoid stacked cutout-looking borders around every card.
	 local halo=frame(parent,x-2,y-2,w+4,h+4,T.deep,6,(r or 18)+2)
	 -- Shadow only. A second neon UIStroke on each card looked like pasted-on borders.
	 halo.BackgroundTransparency=.97
	 local body=frame(parent,x,y,w,h,T.panel,7,r or 17)
	 grad(body,Color3.fromRGB(17,17,17),Color3.fromRGB(5,5,5),25)
	 -- Defined grey contour, not a white neon frame.
	 edge(body,Color3.fromRGB(164,164,164),1.2,.27)
	 return body
	end
	local icon -- forward declaration: glyphBox uses this before the function body is defined
	local function glyphBox(parent,mark,x,y,size)
	 local p=frame(parent,x,y,size,size,Color3.fromRGB(22,22,22),12,14)
	 grad(p,Color3.fromRGB(28,28,28),Color3.fromRGB(10,10,10),90)
	 edge(p,T.glow,1,.45)
	 local iconName=({['✓']='check',['▱']='layers',['∿']='pulse',['◇']='cube',['⚙']='settings'})[mark]
	 if not iconName or not icon(p,iconName,math.floor(size*.17),math.floor(size*.17),
	   math.floor(size*.66),math.floor(size*.66),T.primary,17) then
	  text(p,mark,0,0,size,size,math.floor(size*.57),T.primary,true,14,Enum.TextXAlignment.Center)
	 end
	 return p
	end
	local function connect(signal,func,target)
	 local c=signal:Connect(func)
	 table.insert(target or navHandlers,c)
	 return c
	end
	local function clearPage()
	 for _,c in ipairs(pageHandlers) do pcall(function()c:Disconnect()end)end
	 table.clear(pageHandlers)
	 for _,it in ipairs(content:GetChildren()) do it:Destroy() end
	 table.clear(dynamicControls)
	end
	local function interactive(parent,name,x,y,w,h,fn,bg,accent,persistent)
	 local p,s=pos(x,y,w,h)
	 local relativeZ=parent:IsA('GuiObject') and parent.ZIndex or 1
	 local b=obj('TextButton',parent,{Name=name,Position=p,Size=s,Text=name,
	  Font=Enum.Font.GothamBold,TextSize=19,TextColor3=T.white,
	  BackgroundColor3=bg or T.panel2,AutoButtonColor=false,BorderSizePixel=0,ZIndex=math.max(40,relativeZ+5)})
	 round(b,11);edge(b,accent or T.glow,1,.45)
	 b.Selectable=true
	 connect(b.MouseButton1Click,function()
	  local ok,err=guarded('UI/'..name,fn)
	  if not ok then log('ERROR','UI',tostring(err)) end
	 end,persistent and navHandlers or pageHandlers)
	 local list=persistent and navHandlers or pageHandlers
	 local press=obj('UIScale',b,{Scale=1})
	 local st=FX.strokeOf(b)
	 local baseT=st and st.Transparency or .45
	 connect(b.MouseEnter,function()
	  tw(b,.16,{BackgroundColor3=Color3.fromRGB(38,38,38)})
	  if st then tw(st,.16,{Transparency=.02,Thickness=1.6}) end
	 end,list)
	 connect(b.MouseLeave,function()
	  tw(b,.22,{BackgroundColor3=bg or T.panel2})
	  if st then tw(st,.22,{Transparency=baseT,Thickness=1}) end
	  tw(press,.18,{Scale=1})
	 end,list)
	 connect(b.MouseButton1Down,function() tw(press,.08,{Scale=.95},Enum.EasingStyle.Quad) end,list)
	 connect(b.MouseButton1Up,function() tw(press,.3,{Scale=1},Enum.EasingStyle.Back) end,list)
	 return b
	end
	local function say(msg,err)
	 log(err and 'ERROR' or 'INFO','UI',msg)
	 -- Feedback must appear in the VISIBLE window; the old compact UI wrote only to hidden desktop toast.
	 local box,label=toastBox,toastText
	 if UI.compactMode and compactToast and compactToast.Parent then
	  box,label=compactToast,compactToastText
	 end
	 if not box or not box.Parent or not label then return end
	 label.Text=tostring(msg)
	 box.BackgroundColor3=err and Color3.fromRGB(76,28,28) or Color3.fromRGB(24,24,24)
	 local accent=box:FindFirstChild('FXAccent')
	 if accent then accent.BackgroundColor3=err and T.danger or T.primary end
	 -- Slide-up + spring entrance, slide-down exit.
	 local baseY=box:GetAttribute('baseY')
	 if not baseY then baseY=box.Position.Y.Offset;box:SetAttribute('baseY',baseY) end
	 local x=box.Position.X.Offset
	 box.Position=UDim2.fromOffset(x,baseY+18)
	 box.Visible=true
	 tw(box,.38,{Position=UDim2.fromOffset(x,baseY)},Enum.EasingStyle.Back)
	 FX.typewrite(label,.28)
	 local token=os.clock();box:SetAttribute('token',token)
	 task.delay(3.1,function()
	  if aliveUI and box and box.Parent and box:GetAttribute('token')==token then
	   tw(box,.2,{Position=UDim2.fromOffset(x,baseY+18)},Enum.EasingStyle.Quad,Enum.EasingDirection.In)
	   task.delay(.21,function()
	    if box.Parent and box:GetAttribute('token')==token then box.Visible=false;box.Position=UDim2.fromOffset(x,baseY) end
	   end)
	  end
	 end)
	end
	UI.notify=function(m) say(m) end
	-- This is a warning only; no Roblox idle-timeout bypass is claimed.
	runtimeState.idleNotice = function(message)
	    say(message, true)
	end
	local function applySetting(key,value)
	 local ok,err=setOption(key,value)
	 if not ok then say(tostring(err),true);return false end
	 return true
	end
	-- Optional hotkey to collapse/expand the whole UI. Off by default (toggleKey="");
	-- rebound live from the Settings page without needing a restart.
	local toggleKeyConn
	local function applyToggleKeybind()
	 if toggleKeyConn then pcall(function() toggleKeyConn:Disconnect() end);toggleKeyConn=nil end
	 local keyName=settings.toggleKey
	 if type(keyName)~='string' or keyName=='' then return end
	 local ok,keyCode=pcall(function() return Enum.KeyCode[keyName] end)
	 if not ok or typeof(keyCode)~='EnumItem' then return end
	 toggleKeyConn=connect(UserInputService.InputBegan,function(input,processed)
	  if processed or not aliveUI then return end
	  if input.KeyCode==keyCode then setMinimized(not UI.isMinimized) end
	 end,navHandlers)
	end
	local function toggle(parent,key,x,y,enabledLabel)
	 local w,h=65,36
	 local holder=frame(parent,x,y,w,h,T.off,30,18)
	 edge(holder,T.primary,1,.6)
	 local circle=frame(holder,4,4,28,28,T.muted,32,14)
	 local b=obj('TextButton',holder,{Text='',Size=UDim2.fromScale(1,1),BackgroundTransparency=1,ZIndex=35})
	 local function redraw(animate)
	  local on=(settings[key]==true)
	  local col=on and Color3.fromRGB(82,216,25) or T.off
	  local p=UDim2.fromOffset(on and 33 or 4,4)
	  local cc=on and T.white or T.muted
	  if animate then
	   tw(holder,.22,{BackgroundColor3=col})
	   tw(circle,.32,{Position=p,BackgroundColor3=cc},Enum.EasingStyle.Back)
	  else
	   holder.BackgroundColor3=col;circle.Position=p;circle.BackgroundColor3=cc
	  end
	 end
	 redraw()
	 connect(b.MouseButton1Click,function()
	  if applySetting(key,not settings[key]) then
	   redraw(true)
	   say((enabledLabel or key)..' · '..(settings[key] and 'ON' or 'OFF'))
	  end
	 end,pageHandlers)
	 return holder
	end
	local function confirmAction(title,desc,fn)
	 if dialog then dialog:Destroy();dialog=nil end
	 dialog=frame(shell,0,0,W,H,Color3.new(0,0,0),100,0)
