	 bl.TextWrapped=true
	 local no=interactive(modal,'Cancel',261,215,128,51,function()dialog:Destroy();dialog=nil end)
	 local yes=interactive(modal,'Confirm',403,215,137,51,function()
	  dialog:Destroy();dialog=nil
	  fn()
	 end,Color3.fromRGB(77,30,33),T.danger)
	 no.ZIndex=112;yes.ZIndex=112
	end
	
	local function image(parent,uri,x,y,w,h,z,style)
	 if not uri or uri=='' then return end
	 local p,s=pos(x,y,w,h)
	 return obj('ImageLabel',parent,{Image=uri,Position=p,Size=s,
	  BackgroundTransparency=1,ScaleType=style or Enum.ScaleType.Fit,ZIndex=z or 12})
	end
	local assets={leaf='',logo='',mascot='',swash='',topwave='',bannerwave='',icons='',dots='',chibi='',leaves=''}
	local function loadAsset(name,b64)
	 local loader=type(getcustomasset)=='function' and getcustomasset
	    or type(getsynasset)=='function' and getsynasset or nil
	 if type(writefile)~='function' or not loader then
	  status('Artwork', 'Image APIs not available: '..name)
	  return ''
	 end
	 local success,ret=pcall(function()
	  -- Decode in a protected section. One bad picture must never abort UI startup.
	  if type(b64)~='string' or b64=='' then return '' end
	  local f='RUMScript_Native_'..name..'_lite.png'
	  local bytes
	  if type(isfile)=='function' then
	   local okFile,has=pcall(isfile,f)
	   if okFile and has then
	    local cached=loader(f)
	    if type(cached)=='string' and cached~='' then return cached end
	   end
	  end
	  bytes=decodeBase64(b64)
	  if bytes:sub(1,8)~='\137PNG\r\n\26\n' then error('Invalid PNG signature: '..name) end
	  writefile(f,bytes)
	  return loader(f)
	 end)
	 if not success or type(ret)~='string' or ret=='' then
	  log('ERROR','Artwork','Asset load failed: '..name..' '..tostring(ret))
	  return ''
	 end
	 return ret
	end
	
	local atlasCells={check={0,0},layers={1,0},pulse={2,0},cube={3,0},
	 home={0,1},player={1,1},settings={2,1},search={3,1},
	 sparkle={0,2},moon={1,2},bell={2,2},leaf={3,2}}
	icon = function(parent,name,x,y,w,h,tint,z)
	 local cell=atlasCells[name]
	 if not cell or assets.icons=='' then return nil end
	 local p,s=pos(x,y,w,h)
	 return obj('ImageLabel',parent,{Image=assets.icons,Position=p,Size=s,
	  ImageRectSize=Vector2.new(128,128),ImageRectOffset=Vector2.new(cell[1]*128,cell[2]*128),
	  BackgroundTransparency=1,ImageColor3=tint or T.primary,
	  ScaleType=Enum.ScaleType.Fit,ZIndex=z or 19})
	end
	
