	local function paintNav(tab)
	 if UI.navRail and UI.navY and UI.navY[tab] then
	  local y=UI.navY[tab]
	  tw(UI.navRail[1],.42,{Position=UDim2.fromOffset(5,y+10)},Enum.EasingStyle.Back)
	  tw(UI.navRail[2],.5,{Position=UDim2.fromOffset(2,y+4)},Enum.EasingStyle.Quint)
	 end
	 for name,button in pairs(UI.navButtons) do
	  local on=(name==tab)
	  if UI.navGlows and UI.navGlows[name] then UI.navGlows[name].Visible=on end
	  -- Plain vivid lime; the old yellow-green gradient made selected tabs look muddy.
	  local gradient=button:FindFirstChildOfClass('UIGradient')
	  if gradient then gradient.Enabled=false end
	  tw(button,.25,{BackgroundColor3=on and T.primary or T.panel2})
	  local outline=button:FindFirstChildOfClass('UIStroke')
	  if outline then
	   outline.Color=on and T.primary or Color3.fromRGB(137,137,137)
	   outline.Thickness=on and 1.5 or 1.15
	   outline.Transparency=on and .08 or .4
	  end
	  for _,child in ipairs(button:GetChildren()) do
	   if child:IsA('TextLabel') then child.TextColor3=on and T.bg or T.white end
	   if child:IsA('ImageLabel') then child.ImageColor3=on and T.bg or T.white end
	  end
	 end
	end
