	local function plusMinus(parent,key,x,y,maxVal,step)
	 local width=385
	 local slider=frame(parent,x,y,width,12,T.off,16,7)
	 local fill=frame(slider,0,0,1,12,T.primary,17,7)
	 local knob=frame(slider,0,-9,28,28,T.white,18,14)
	 edge(knob,T.primary,1,.12)
	 local info=text(parent,'',x+width-90,y-52,90,37,29,T.primary,true,20,Enum.TextXAlignment.Right)
	 local draggingPointer=nil
	 local preview=nil
	 local function quantize(v)
	  return math.clamp(math.floor(v/step+.5)*step,0,maxVal)
	 end
	 local function paint(v)
	  local q=math.clamp(v/maxVal,0,1)
	  fill.Size=UDim2.fromOffset(math.max(3,math.floor(width*q)),12)
	  knob.Position=UDim2.fromOffset(math.clamp(math.floor(width*q)-14,0,width-27),-8)
	  info.Text=tostring(v)
	 end
	 local function commit(v)
	  if applySetting(key,quantize(v)) then paint(settings[key])
	  else paint(settings[key]) end
	 end
	 local function fromInput(inp)
	  local abs=slider.AbsolutePosition
	  local den=slider.AbsoluteSize.X
	  if den>1 then
	   preview=quantize((inp.Position.X-abs.X)/den*maxVal)
	   paint(preview)
	  end
	 end
	 paint(settings[key])
	 local track=obj('TextButton',parent,{Text='',BackgroundTransparency=1,
	  Position=UDim2.fromOffset(x-8,y-16),Size=UDim2.fromOffset(width+16,43),ZIndex=23})
	 connect(track.InputBegan,function(inp)
	  if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
	   draggingPointer=inp
	   preview=settings[key]
	   fromInput(inp)
	  end
	 end,pageHandlers)
	 connect(UserInputService.InputChanged,function(inp)
	  if not draggingPointer then return end
	  if draggingPointer.UserInputType==Enum.UserInputType.Touch then
	   if inp==draggingPointer then fromInput(inp) end
	  elseif inp.UserInputType==Enum.UserInputType.MouseMovement then
	   fromInput(inp)
	  end
	 end,pageHandlers)
	 connect(UserInputService.InputEnded,function(inp)
	  if not draggingPointer then return end
	  local isMouse=draggingPointer.UserInputType==Enum.UserInputType.MouseButton1
	    and inp.UserInputType==Enum.UserInputType.MouseButton1
	  local isTouch=draggingPointer.UserInputType==Enum.UserInputType.Touch and inp==draggingPointer
	  if isMouse or isTouch then
	   draggingPointer=nil
	   local nextValue=preview or settings[key]
	   preview=nil
	   commit(nextValue)
	  end
	 end,pageHandlers)
	 interactive(parent,'−',x,y+37,50,44,function()commit(settings[key]-step)end)
	 interactive(parent,'+',x+60,y+37,50,44,function()commit(settings[key]+step)end)
	 interactive(parent,'Reset',x+width-109,y+37,108,44,function()commit(defaults[key])end)
	end
