	local function segmented(p,values,selected,x,y,full,key)
	 local gap=8
	 local bw=(full-(#values-1)*gap)/#values
	 for i,labelValue in ipairs(values) do
	  local val=tostring(labelValue)
	  local selectedNow=(tostring(selected)==val)
	  local b=interactive(p,val,x+(i-1)*(bw+gap),y,bw,44,function()
	   if applySetting(key,val) then UI.show(currentPage) end
	  end,selectedNow and Color3.fromRGB(87,201,25) or T.panel2,
	    selectedNow and T.primary or Color3.fromRGB(85,85,85))
	  b.TextSize=17
	  if selectedNow then b.TextColor3=T.bg end
	 end
	end
