	 local keyLabel=text(keyBox,settings.toggleKey~='' and settings.toggleKey or 'None',0,0,150,44,17,T.white,true,14,Enum.TextXAlignment.Center)
	 text(profiles,'Click the box, then press any key (Esc cancels)',428,152,475,44,15,T.muted,false,14)
	 local capturing=false
