	-- COMPACT LANDSCAPE: independent legible layout, not a scaled-down 1296x730 canvas.
	-- Used only for narrower screens. All components are native Roblox UI objects.
	local compactMain, compactScale, compactContent
	local compactNav = {}
	-- ---------------- WINDOW CHOREOGRAPHY (V8) ----------------
	function FX.active()
	 if UI.compactMode then return compactMain,compactScale,UI.fxCompact,UI.compactTarget,compactContent end
	 return main,scaling,UI.fxWide,UI.wideTarget,content
	end
	local function miniCenter()
	 -- mini uses AnchorPoint .5,.5 so its Position IS its centre.
	 if mini then return UDim2.fromOffset(mini.Position.X.Offset,mini.Position.Y.Offset) end
	 return UDim2.fromOffset(40,36)
	end
	function FX.popMini()
	 if not mini or not UI.miniScale then return end
	 UI.miniScale.Scale=0
	 tw(UI.miniScale,.5,{Scale=1},Enum.EasingStyle.Back)
	end
	-- Window implodes with a neon flare, then flies into the floating logo.
	function FX.collapse()
	 local win,sc,fx,target=FX.active()
	 if not win or not sc then return end
	 UI.animating=true
	 UI.restorePos=win.Position
	 local base=target or sc.Scale
	 if fx and fx.veil then
	  fx.veil.Visible=true;fx.veil.BackgroundTransparency=1
	  tw(fx.veil,.24,{BackgroundTransparency=0},Enum.EasingStyle.Quad)
	 end
	 if fx and fx.chrome then tw(fx.chrome,.14,{Thickness=(fx.chromeThick or 2)+4},Enum.EasingStyle.Quad) end
	 tw(sc,.12,{Scale=base*1.025},Enum.EasingStyle.Quad)
	 task.delay(.12,function()
	  tw(sc,.38,{Scale=.03},Enum.EasingStyle.Quint,Enum.EasingDirection.In)
	  tw(win,.38,{Position=miniCenter()},Enum.EasingStyle.Quint,Enum.EasingDirection.In)
	 end)
	 task.delay(.52,function()
	  if not aliveUI then return end
	  win.Visible=false
	  win.Position=UI.restorePos
	  sc.Scale=base
	  if fx and fx.veil then fx.veil.Visible=false end
	  if fx and fx.chrome then fx.chrome.Thickness=fx.chromeThick or 2 end
	  if mini then mini.Visible=true end
	  FX.popMini()
	  UI.animating=false
	 end)
	end
	-- Logo shrinks, window bursts out of it with a spring, veil dissolves, scanline sweeps.
	function FX.expand()
	 local win,sc,fx,target,container=FX.active()
	 if not win or not sc then return end
	 UI.animating=true
	 if UI.miniScale then tw(UI.miniScale,.17,{Scale=0},Enum.EasingStyle.Back,Enum.EasingDirection.In) end
	 task.delay(.17,function()
	  if not aliveUI then return end
	  if mini then mini.Visible=false end
	  if UI.miniScale then UI.miniScale.Scale=1 end
	  local dest=UI.restorePos or UDim2.fromScale(.5,.5)
	  win.Position=miniCenter()
	  sc.Scale=.03
	  if fx and fx.veil then fx.veil.Visible=true;fx.veil.BackgroundTransparency=0 end
	  win.Visible=true
	  tw(win,.5,{Position=dest},Enum.EasingStyle.Quint)
	  tw(sc,.6,{Scale=target or 1},Enum.EasingStyle.Back)
	  if fx and fx.veil then tw(fx.veil,.42,{BackgroundTransparency=1},Enum.EasingStyle.Quad,nil,.2) end
	  task.delay(.62,function()
	   if fx and fx.veil then fx.veil.Visible=false end
	   UI.animating=false
	   if refreshWindowScale then refreshWindowScale() end
	   FX.flash(fx)
	   FX.pageIn(container)
	  end)
	 end)
	end
	-- Boot terminal: decoded wordmark, typed log lines, progress bar, dissolve.
	function FX.boot()
	 local win,sc,fx,target,container=FX.active()
	 if not win or not sc then return end
	 if FX.lite then UI.booting=false;UI.animating=false;return end
	 local compact=UI.compactMode
	 local host=compact and compactMain or main
	 local L=compact and {x=6,y=5,w=601,h=312,r=13,z=68,ring=56,ringY=13,titleY=76,titleH=28,titleS=22,
	   subY=104,subS=10,linesY=126,lineH=15,lineS=10,lineW=300,barY=208,pctY=214,pctS=10}
	  or {x=29,y=23,w=W-58,h=H-46,r=29,z=70,ring=130,ringY=86,titleY=232,titleH=52,titleS=42,
	   subY=288,subS=15,linesY=330,lineH=26,lineS=15,lineW=520,barY=478,pctY=490,pctS=13}
	 UI.animating=true;UI.booting=true
	 local o=frame(host,L.x,L.y,L.w,L.h,T.bg,L.z,L.r);o.Active=false
	 local cx=math.floor(L.w/2)
	 FX.ring(o,cx-math.floor(L.ring/2),L.ringY,L.ring,L.z+1,compact and 2 or 3,260)
	 local inner=frame(o,cx-math.floor(L.ring*.3),L.ringY+math.floor(L.ring*.2),math.floor(L.ring*.6),math.floor(L.ring*.6),T.primary,L.z+1,math.ceil(L.ring*.3))
	 inner.BackgroundTransparency=.85
	 FX.pulse(inner,'BackgroundTransparency',.7,.95,.8)
	 -- Logo in the centre of the spinning ring.
	 if assets.logo~='' then
	  local ls=math.floor(L.ring*.7)
	  local li=image(o,assets.logo,cx-math.floor(ls/2),L.ringY+math.floor((L.ring-ls)/2),ls,ls,L.z+3)
	  if li then
	   li.ImageTransparency=1
	   tw(li,.45,{ImageTransparency=0},Enum.EasingStyle.Quad)
	  end
	 end
	 local title=obj('TextLabel',o,{Position=UDim2.fromOffset(0,L.titleY),Size=UDim2.fromOffset(L.w,L.titleH),
	  BackgroundTransparency=1,Font=Enum.Font.GothamBold,TextSize=L.titleS,TextColor3=T.white,
	  Text='RUMSCRIPT',ZIndex=L.z+2,TextXAlignment=Enum.TextXAlignment.Center})
	 FX.decode(title,'RUMSCRIPT',.5)
	 task.delay(.55,function()
	  if title.Parent then title.RichText=true;title.Text='<font color="#F9FCF7">RUM</font><font color="#79FF26">Script</font>' end
	 end)
	 local sub=FX.mono(o,'CORE INTERFACE  //  V8 FX',0,L.subY,L.w,L.subS+6,L.subS,T.primary,L.z+2,Enum.TextXAlignment.Center)
	 FX.typewrite(sub,.4,.1)
	 local function row(name,state)
	  local dots=string.rep('.',math.max(2,30-#name))
	  return '> '..name..' '..dots..' '..state
	 end
	 local lines={row('core.init','OK'),row('native interface','OK'),row('pages [home/player/settings]','OK'),
	  row('artwork',assets.logo~='' and 'OK' or 'FALLBACK'),row('fx engine','ONLINE')}
	 local lx=cx-math.floor(L.lineW/2)
	 for i,str in ipairs(lines) do
	  local lbl=FX.mono(o,str,lx,L.linesY+(i-1)*L.lineH,L.lineW,L.lineH,L.lineS,
	   i==#lines and T.primary or Color3.fromRGB(170,170,170),L.z+2)
	  lbl.Visible=false
	  task.delay(.12+i*.12,function()
	   if lbl.Parent then lbl.Visible=true;FX.typewrite(lbl,.14) end
	  end)
	 end
	 local track=frame(o,lx,L.barY,L.lineW,compact and 3 or 4,Color3.fromRGB(40,40,40),L.z+2,2)
	 local fill=frame(track,0,0,0,compact and 3 or 4,T.primary,L.z+3,2)
	 local pct=FX.mono(o,'0%',lx,L.pctY,L.lineW,L.pctS+6,L.pctS,T.muted,L.z+2,Enum.TextXAlignment.Right)
	 local tag=FX.mono(o,'BOOTING',lx,L.pctY,L.lineW,L.pctS+6,L.pctS,T.muted,L.z+2)
	 tw(fill,.95,{Size=UDim2.fromOffset(L.lineW,compact and 3 or 4)},Enum.EasingStyle.Quad,Enum.EasingDirection.InOut,.1)
	 task.spawn(function()
	  local t0=os.clock()
	  while aliveUI and pct.Parent do
	   local k=math.clamp((os.clock()-t0-.1)/.95,0,1)
	   pct.Text=tostring(math.floor(k*100+.5))..'%'
	   if k>=1 then break end
	   task.wait(.03)
	  end
	  if tag.Parent then tag.Text='READY';tag.TextColor3=T.primary end
	 end)
	 -- Window itself springs open underneath the overlay.
	 sc.Scale=(target or sc.Scale)*.88
	 tw(sc,.7,{Scale=target or 1},Enum.EasingStyle.Back)
	 task.delay(1.2,function()
	  if not aliveUI then return end
	  FX.pulses[inner]=nil
	  FX.fadeOut(o,.38)
	  FX.flash(fx)
	  task.delay(.4,function()
	   if o.Parent then o:Destroy() end
	   UI.animating=false;UI.booting=false
	   if refreshWindowScale then refreshWindowScale() end
	   UI.lastShown=nil
	   UI.show(currentPage)
	  end)
	 end)
	end
	setMinimized = function(value)
	 value=value and true or false
	 if UI.animating then return end
	 if (UI.isMinimized==true)==value then return end
	 UI.isMinimized=value
	 if value then FX.collapse() else FX.expand() end
	 status('Window', UI.isMinimized and 'Collapsed to draggable RUM Script logo' or 'Restored')
	end
	toggleWindowSize = function()
	 if UI.animating then return end
	 UI.windowExpanded=not UI.windowExpanded
	 if UI.windowExpanded then
	  -- Expansion is always centered so a previously dragged window cannot overflow.
	  if main then tw(main,.45,{Position=UDim2.fromScale(.5,.5)}) end
	  if compactMain then tw(compactMain,.45,{Position=UDim2.fromScale(.5,.5)}) end
	 end
	 UI.smoothNext=true
	 if refreshWindowScale then refreshWindowScale() end
	 local _,_,fx=FX.active();FX.flash(fx)
	 status('Window size',UI.windowExpanded and 'Expanded (fitted within viewport)' or 'Normal size')
	end
	local compactDialog
	local CW,CH=613,322
	local function cText(parent,label,x,y,w,h,px,fg,bold)
	 local t=text(parent,label,x,y,w,h,px,fg or T.white,bold,28)
	 -- This label is already physically sized for a compact viewport. Do not inflate it.
	 readableLabels[t]=nil
	 compactCopies[t]=nil
	 t.TextSize=px
	 return t
	end
	local function cPanel(parent,x,y,w,h,r)
	 -- Impeccable/distill: one muted contour; glow belongs only to important active states.
	 local box=frame(parent,x,y,w,h,T.panel,18,r or 10)
	 edge(box,Color3.fromRGB(164,164,164),1.15,.27)
	 return box
	end
	local function cButton(parent,label,x,y,w,h,callback,isDanger,persistent,isSelected)
	 -- A segmented option must show its REAL selection; previous version drew
	 -- Low/Balanced/High identically regardless of the stored preference.
	 local normal=T.panel2
	 local active=Color3.fromRGB(50,50,50)
	 local danger=Color3.fromRGB(65,27,30)
	 local b=frame(parent,x,y,w,h,isDanger and danger or (isSelected and active or normal),31,7)
	 local outline=edge(b,isDanger and T.danger or (isSelected and T.primary or Color3.fromRGB(134,134,134)),1.1,isSelected and .1 or .4)
	 local fontSize=(w<=50 and #label>=6) and 11 or ((w<=65 and #label>=7) and 12 or ((h>=38 and w>=110) and 14 or 13))
	 cText(b,label,2,0,w-4,h,fontSize,isDanger and T.danger or T.white,true).TextXAlignment=Enum.TextXAlignment.Center
	 local hbtn=obj('TextButton',b,{Text='',BackgroundTransparency=1,Size=UDim2.fromScale(1,1),ZIndex=40})
	 local handlers=persistent and navHandlers or pageHandlers
	 local press=obj('UIScale',b,{Scale=1})
	 local st=FX.strokeOf(b)
	 local baseT=st and st.Transparency or .4
	 connect(hbtn.MouseEnter,function()
	  if not isSelected then tw(b,.15,{BackgroundColor3=isDanger and Color3.fromRGB(88,35,38) or Color3.fromRGB(35,35,35)}) end
	  if st then tw(st,.15,{Transparency=.02}) end
	 end,handlers)
	 connect(hbtn.MouseLeave,function()
	  tw(b,.2,{BackgroundColor3=isDanger and danger or (isSelected and active or normal)})
	  if st then tw(st,.2,{Transparency=baseT}) end
	  tw(press,.18,{Scale=1})
	 end,handlers)
	 connect(hbtn.MouseButton1Down,function() tw(press,.08,{Scale=.94},Enum.EasingStyle.Quad) end,handlers)
	 connect(hbtn.MouseButton1Up,function() tw(press,.3,{Scale=1},Enum.EasingStyle.Back) end,handlers)
	 connect(hbtn.MouseButton1Click,function()
	  local ok,err=guarded('Compact '..label,callback)
	  if not ok then say(tostring(err),true) end
	 end,handlers)
	 return b
	end
	local function cToggle(parent,key,x,y)
	 local holder=frame(parent,x,y,39,20,T.off,32,10)
	 edge(holder,T.glow,1,.55)
	 local dot=frame(holder,2,2,16,16,T.muted,33,8)
	 local function draw(animate)
	  local on=settings[key]==true
	  local col=on and Color3.fromRGB(82,216,25) or T.off
	  local p=UDim2.fromOffset(on and 21 or 2,2)
	  local cc=on and T.white or T.muted
	  if animate then
	   tw(holder,.2,{BackgroundColor3=col})
	   tw(dot,.3,{Position=p,BackgroundColor3=cc},Enum.EasingStyle.Back)
	  else
	   holder.BackgroundColor3=col;dot.Position=p;dot.BackgroundColor3=cc
	  end
	 end
	 draw()
	 local hit=obj('TextButton',holder,{Text='',BackgroundTransparency=1,Size=UDim2.fromScale(1,1),ZIndex=40})
	 connect(hit.MouseButton1Click,function()
	  if applySetting(key,not settings[key]) then
	   draw(true)
	   if key=='antiAFK' then say('Anti AFK input requested; see Debug for results')
	   else say(key..': '..(settings[key] and 'ON' or 'OFF')) end
	  end
	 end,pageHandlers)
	 return holder
	end
	local function cTitle(parent,name,desc)
	 local bar=frame(parent,1,5,3,28,T.primary,23,2)
	 local tl=cText(parent,name,12,2,254,27,22,T.white,true)
	 local dl=desc and cText(parent,desc,12,30,420,17,13,T.muted,false)
	 FX.mono(parent,'//'..string.upper(name),300,8,148,16,10,Color3.fromRGB(95,95,95),28,Enum.TextXAlignment.Right)
	 if UI.pageChanged then
	  bar.Size=UDim2.fromOffset(3,0)
	  tw(bar,.4,{Size=UDim2.fromOffset(3,28)},Enum.EasingStyle.Quint)
	  FX.decode(tl,name,.34)
	  if dl then FX.typewrite(dl,.45,.1) end
	 end
	end
	local function cStatsCard(x,title,value,which)
	 local p=cPanel(compactContent,x,55,144,49,10)
	 local badge=frame(p,10,10,29,29,Color3.fromRGB(24,64,29),23,8)
	 if not icon(badge,which,4,4,21,21,T.primary,28) then cText(badge,'•',6,1,20,25,19,T.primary,true) end
	 cText(p,title,47,7,91,17,12,T.muted,false)
	 cText(p,value,47,23,91,23,17,title=='Status' and T.primary or T.white,true)
	end
	local function cConfirm(title,body,fn)
	 if compactDialog then compactDialog:Destroy();compactDialog=nil end
	 compactDialog=frame(compactMain,0,0,CW,CH,Color3.new(0,0,0),90,0)
	 compactDialog.BackgroundTransparency=.18
	 local p=cPanel(compactDialog,119,73,382,172,12)
	 p.ZIndex=94
	 cText(p,title,17,14,350,30,17,T.white,true).ZIndex=96
	 local msg=cText(p,body,17,51,350,52,12,T.muted,false)
	 msg.TextWrapped=true;msg.ZIndex=96
	 local no=cButton(p,'Cancel',95,118,85,35,function()compactDialog:Destroy();compactDialog=nil end)
	 local yes=cButton(p,'Confirm',198,118,95,35,function()
	  compactDialog:Destroy();compactDialog=nil
	  fn()
	 end,true)
	 no.ZIndex=97;yes.ZIndex=97
	end
	local function cStepValue(parent,key,x,y,w,maxVal,step)
	 -- The slider must react to dragging, not just a click at its initial position.
	 -- Changes remain visual during drag; the actual setting is committed once on release
	 -- to avoid dozens of writes and server/client updates per second.
	 local value=cText(parent,tostring(settings[key]),x+w-48,y-4,48,24,18,T.primary,true)
	 value.TextXAlignment=Enum.TextXAlignment.Right
	 local line=frame(parent,x,y+32,w,6,T.off,23,3)
	 local bar=frame(line,0,0,1,6,T.primary,24,3)
	 local dot=frame(line,0,-3,12,12,T.white,25,6)
	 local activePointer=nil
	 local previewValue=nil
	 local function paint(amount)
	  value.Text=tostring(amount)
	  local frac=math.clamp(amount/maxVal,0,1)
	  bar.Size=UDim2.fromOffset(math.max(2,math.floor(w*frac)),6)
	  dot.Position=UDim2.fromOffset(math.clamp(math.floor(w*frac)-6,0,w-12),-3)
	 end
	 local function quantize(raw)
	  return math.clamp(math.floor(raw/step+.5)*step,0,maxVal)
	 end
	 local function commit(v)
	  if applySetting(key,quantize(v)) then
	   paint(settings[key])
	  else
	   paint(settings[key]) -- restore confirmed value after a failed request
	  end
	 end
	 local function updateFromPointer(pointer)
	  -- Use actual GUI pixel bounds. Correct when the whole compact UI is scaled.
	  local width=line.AbsoluteSize.X
	  if width<=0 then return end
	  local frac=math.clamp((pointer.Position.X-line.AbsolutePosition.X)/width,0,1)
	  previewValue=quantize(frac*maxVal)
	  paint(previewValue)
	 end
	 paint(settings[key])
	 local click=obj('TextButton',parent,{Text='',BackgroundTransparency=1,
	  Position=UDim2.fromOffset(x,y+23),Size=UDim2.fromOffset(w,25),ZIndex=40})
	 connect(click.InputBegan,function(inp)
	  if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
	   activePointer=inp
	   previewValue=settings[key]
	   updateFromPointer(inp)
	  end
	 end,pageHandlers)
	 connect(UserInputService.InputChanged,function(inp)
	  if not activePointer then return end
	  if activePointer.UserInputType==Enum.UserInputType.Touch then
	   if inp==activePointer then updateFromPointer(inp) end
	  elseif inp.UserInputType==Enum.UserInputType.MouseMovement then
	   updateFromPointer(inp)
	  end
	 end,pageHandlers)
	 connect(UserInputService.InputEnded,function(inp)
	  if not activePointer then return end
	  local isMouse=activePointer.UserInputType==Enum.UserInputType.MouseButton1
	   and inp.UserInputType==Enum.UserInputType.MouseButton1
	  local isTouch=activePointer.UserInputType==Enum.UserInputType.Touch and inp==activePointer
	  if isMouse or isTouch then
	   local v=previewValue or settings[key]
	   activePointer=nil
	   previewValue=nil
	   commit(v)
	  end
	 end,pageHandlers)
	 cButton(parent,'−',x,y+53,34,34,function()commit(settings[key]-step)end)
	 cButton(parent,'+',x+39,y+53,34,34,function()commit(settings[key]+step)end)
	 cButton(parent,'Reset',x+w-76,y+53,76,34,function()commit(defaults[key])end)
	end
	local function compactRender(page)
	 if not compactContent then return end
	 if compactDialog then compactDialog:Destroy();compactDialog=nil end
	 for _,connection in ipairs(pageHandlers) do pcall(function()connection:Disconnect()end)end
	 table.clear(pageHandlers)
	 for _,child in ipairs(compactContent:GetChildren())do child:Destroy()end
	 compactContent.CanvasPosition=Vector2.new(0,0)
	 -- Give each page its own scroll extent. This avoids clipped bottom-row controls.
	 -- Provide enough actual scrollable space for legible 32px action buttons.
	 local pageHeight=(page=='Home' and 445) or (page=='Player' and 604) or 781
	 compactContent.CanvasSize=UDim2.fromOffset(0,pageHeight)
	 compactContent.ScrollBarThickness=4
	 if UI.cNavRail and UI.cNavY and UI.cNavY[page] then
	  tw(UI.cNavRail,.4,{Position=UDim2.fromOffset(3,UI.cNavY[page]+6)},Enum.EasingStyle.Back)
	 end
	 for name,button in pairs(compactNav)do
	  local on=(name==page)
	  tw(button,.22,{BackgroundColor3=on and T.primary or T.panel2})
	  for _,label in ipairs(button:GetChildren()) do
	   if label:IsA('TextLabel') then label.TextColor3=on and T.bg or T.white end
	   if label:IsA('ImageLabel') then label.ImageColor3=on and T.bg or T.white end
	  end
	  local stroke=button:FindFirstChildOfClass('UIStroke')
	  if stroke then
	   stroke.Color=on and T.primary or Color3.fromRGB(137,137,137)
	   stroke.Transparency=on and .1 or .40
	  end
	 end
	 if page=='Home' then
	  -- Calm, functional dashboard. Brand artwork is independent of native labels/controls.
	  cTitle(compactContent,'Home','Your RUM Script workspace')
	  local n=0
	  for _,key in ipairs({'speedEnabled','jumpEnabled','noclip','antiLag'}) do
	   if settings[key] == true then n = n + 1 end
	  end
	  cStatsCard(0,'Status','UI ready','check')
	  cStatsCard(153,'Pages','03','layers')
