	  local heroBrand=cText(hero,'RUMScript',16,43,245,38,26,T.white,true)
	  heroBrand.RichText=true
	  heroBrand.Text='<font color="#F9FCF7">RUM</font><font color="#79FF26">Script</font>'
	  cText(hero,'Control panel · 3 main pages',16,95,253,20,13,T.muted,false)
	  -- Decorative mascot only, with an isolated bounding area. No overlapping text.
	  if assets.chibi~='' then
	   UI.compactChibiImage=image(hero,assets.chibi,270,-10,178,178,24,Enum.ScaleType.Fit)
	  elseif assets.mascot~='' then
	   UI.compactChibiImage=image(hero,assets.mascot,270,-10,178,178,24,Enum.ScaleType.Fit)
	  end
	
	  local quick=cPanel(compactContent,0,273,451,70,12)
	  cText(quick,'Quick preferences',15,9,194,21,16,T.white,true)
	  cText(quick,'Theme',16,39,68,18,13,T.muted,false)
	  local tag=frame(quick,78,34,75,27,T.panel2,24,7)
	  cText(tag,'Dark',0,0,75,27,13,T.primary,true).TextXAlignment=Enum.TextXAlignment.Center
	  cText(quick,'Alerts',277,39,68,18,13,T.muted,false)
	  cToggle(quick,'notifications',394,35)
	
	  local shortcuts=cPanel(compactContent,0,353,451,64,11)
	  cText(shortcuts,'GO TO',15,7,83,19,11,T.primary,true)
	  cText(shortcuts,'Quick actions',15,26,129,25,16,T.white,true)
	  cButton(shortcuts,'Player',160,13,120,38,function()UI.show('Player')end)
	  cButton(shortcuts,'Settings',293,13,142,38,function()UI.show('Settings')end)
	 elseif page=='Player' then
