	  cToggle(cn,'autoReconnect',392,94)
	  cButton(cn,'Rejoin Now',16,140,419,38,function()
	   cConfirm('Rejoin this game?','Attempt a standard Roblox teleport to this place.',function()
	    local ok,err=pcall(function()TeleportService:Teleport(game.PlaceId,player)end)
	    say(ok and 'Rejoin requested, not confirmed' or tostring(err),not ok)
	   end)
