	  cToggle(cfg,'autoSave',392,45)
	  cButton(cfg,'Delete Save',16,86,203,38,function()
	   cConfirm('Delete saved settings?','Remove the local configuration file.',function()
	    if not capability.delete then say('Local deletion unavailable',true);return end
	    local ok,err=pcall(function()delfile(CONFIG.SAVE_FILE)end)
	    if ok then runtimeState.saveRevision+=1;runtimeState.pauseAfterDelete=true;say('Saved preferences deleted')
	    else say('Delete failed: '..tostring(err),true)end
	   end)
	  end,true)
	  cButton(cfg,'Reset All Settings',232,86,202,38,function()
	   cConfirm('Reset all settings?','Restore settings to defaults.',function()
	    for k,v in pairs(defaults)do settings[k]=v end
	    settings.autoSave=capability.save
	    restoreCollisions();applyNoclip();applyAntiAFK();applyMovement('Reset');applyGraphics();applyAutoReconnect();applyAutoExecute()
	    if settings.autoSave then writeSettings()end
	    UI.show('Settings')
	   end)
	  end,true)
	 end
