	 if compactDialog then compactDialog:Destroy();compactDialog=nil end
	 compactDialog=frame(compactMain,0,0,CW,CH,Color3.new(0,0,0),90,0)
	 compactDialog.BackgroundTransparency=.15
	 local p=cPanel(compactDialog,49,24,514,277,10)
	 p.ZIndex=94
	 cText(p,'RUM SCRIPT / DEBUG',15,8,400,30,18,T.primary,true).ZIndex=95
	 local field=obj('TextBox',p,{Text=makeReport(),Position=UDim2.fromOffset(14,44),Size=UDim2.fromOffset(484,180),
	  BackgroundColor3=T.bg,TextColor3=T.white,Font=Enum.Font.Code,TextSize=12,
	  TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,
	  TextEditable=true,MultiLine=true,TextWrapped=false,ClearTextOnFocus=false,ZIndex=97})
	 round(field,7)
