	 cButton(p,'Copy Report',141,233,134,30,function()
	  local cb=type(setclipboard)=='function' and setclipboard or type(toclipboard)=='function' and toclipboard or nil
	  if not cb then field:CaptureFocus();say('Select text manually');return end
	  local ok=pcall(function()cb(makeReport())end)
	  say(ok and 'Report copied' or 'Clipboard unavailable',not ok)
