	 cButton(p,'Close',383,233,112,30,function()compactDialog:Destroy();compactDialog=nil end)
	end
	local function buildCompact()
	 compactMain=frame(root,0,0,CW,CH,T.bg,5,0)
	 -- This host is fully transparent: the rounded body below is the only background.
	 -- Avoid the square, black rectangle outside the neon rounded corners.
	 compactMain.BackgroundTransparency=1
	 compactMain.AnchorPoint=Vector2.new(.5,.5)
	 compactMain.Position=UDim2.fromScale(.5,.5)
	 compactScale=obj('UIScale',compactMain,{Scale=1})
	 -- Dark body stays behind content. Its neon contour is rendered above all panels below.
	 local border=frame(compactMain,6,5,601,312,T.bg,6,13)
	 local side=frame(compactMain,7,6,122,310,T.bg,7,11)
	 frame(compactMain,130,6,1,309,Color3.fromRGB(88,88,88),8)
	 -- Decorative swash removed: it distracted from the navigation and overlapped the footer.
	 -- No sticker leaves in the footer. Keep the sidebar sparse and aligned.
	 -- Logo is exactly half the former 96px size. Preserve the 41px floating restore logo.
	 FX.ring(side,32,9,58,12,1.5,130)
	 if assets.logo~=''then UI.compactLogoImage=image(side,assets.logo,37,14,48,48,13)else
	  cText(side,'RUM',36,18,50,20,15,T.white,true).TextXAlignment=Enum.TextXAlignment.Center
	  cText(side,'SCRIPT',32,37,58,17,11,T.primary,true).TextXAlignment=Enum.TextXAlignment.Center
	 end
	 for i,v in ipairs({{'Home','home'},{'Player','player'},{'Settings','settings'}})do
	  local y=84+(i-1)*40
	  local b=frame(side,10,y,102,33,T.panel2,13,8)
	  edge(b,Color3.fromRGB(137,137,137),1.05,.40)
	  if not icon(b,v[2],11,9,15,15,T.white,16)then cText(b,'◇',11,6,19,21,13,T.white,true)end
	  cText(b,v[1],35,1,65,31,13,T.white,true)
	  local hit=obj('TextButton',b,{Text='',BackgroundTransparency=1,Size=UDim2.fromScale(1,1),ZIndex=24})
	  connect(hit.MouseButton1Click,function()UI.show(v[1])end,navHandlers)
	  compactNav[v[1]]=b
	 end
	 UI.cNavY={Home=84,Player=124,Settings=164}
	 UI.cNavRail=frame(side,3,90,3,21,T.primary,24,2)
	 UI.cNavRail.Active=false
	 UI.cHud=FX.hud(side,10,258,102,44,true,15)
	 frame(compactMain,131,39,469,1,Color3.fromRGB(89,89,89),8)
	 -- The icon and title share a fixed header baseline; no split labels.
	 local compactBrand=cText(compactMain,'RUMScript',140,11,127,25,17,T.white,true)
	 compactBrand.RichText=true
	 compactBrand.Text='<font color="#F9FCF7">RUM</font><font color="#79FF26">Script</font>'
	 cText(compactMain,'Script Hub',271,14,83,23,11,T.muted,false)
	 local search=frame(compactMain,365,10,118,26,T.panel2,16,8)
	 edge(search,Color3.fromRGB(98,98,98),1,.64)
	 local input=obj('TextBox',search,{Position=UDim2.fromOffset(9,2),Size=UDim2.fromOffset(104,22),
	  Text='',PlaceholderText='Find a control...',TextColor3=T.white,PlaceholderColor3=T.muted,
	  BackgroundTransparency=1,Font=Enum.Font.Gotham,TextSize=12,ClearTextOnFocus=false,
	  TextXAlignment=Enum.TextXAlignment.Left,ZIndex=23})
	 connect(input.FocusLost,function(enter)
	  if not enter then return end
	  local q=string.lower(input.Text);input.Text=''
	  if q=='' then return end
	  if q:find('player')or q:find('speed')or q:find('jump')or q:find('noclip') then UI.show('Player')
	  elseif q:find('afk')or q:find('idle')or q:find('setting')or q:find('save')or q:find('graphic')or q:find('fps')or q:find('rejoin') then UI.show('Settings')
	  elseif q:find('debug')or q:find('bug')then compactDebug()
	  elseif q:find('home') then UI.show('Home')
	  else say('No match. Try Player, FPS, AFK or Debug.',true) end
	 end,navHandlers)
	 local dbg=cButton(compactMain,'BUG',487,10,35,24,compactDebug,false,true)
	 cButton(compactMain,'−',526,10,22,24,function()setMinimized(true)end,false,true)
	 cButton(compactMain,'□',553,10,22,24,toggleWindowSize,false,true)
	 cButton(compactMain,'×',580,10,22,24,function()setMinimized(true)end,false,true)
	 -- Drag only from the free top-bar area; do not cover search, BUG or window buttons.
	 -- Clamp the window to the visible screen so the user cannot lose it offscreen.
	 local compactDragging=nil
	 local compactOrigin=nil
	 local compactAnchor=nil
	 local compactHandle=obj('TextButton',compactMain,{
	  Text='',BackgroundTransparency=1,AutoButtonColor=false,
	  Position=UDim2.fromOffset(133,5),Size=UDim2.fromOffset(222,32),ZIndex=30})
	 connect(compactHandle.InputBegan,function(inp)
	  if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
	   compactDragging=inp
	   compactAnchor=inp.Position
	   compactOrigin=compactMain.Position
	  end
	 end,navHandlers)
	 connect(UserInputService.InputChanged,function(inp)
	  if not compactDragging or not compactOrigin or not compactAnchor then return end
	  if compactDragging.UserInputType==Enum.UserInputType.Touch then
	   if inp~=compactDragging then return end
	  elseif inp.UserInputType~=Enum.UserInputType.MouseMovement then return end
	  local v=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
	  if not v then return end
	  local scale=compactScale.Scale
	  local halfW=CW*scale*.5
	  local halfH=CH*scale*.5
	  local targetX=v.X*.5+compactOrigin.X.Offset+(inp.Position.X-compactAnchor.X)
	  local targetY=v.Y*.5+compactOrigin.Y.Offset+(inp.Position.Y-compactAnchor.Y)
	  local x=math.clamp(targetX,halfW,math.max(halfW,v.X-halfW))
	  local y=math.clamp(targetY,halfH,math.max(halfH,v.Y-halfH))
	  compactMain.Position=UDim2.new(.5,x-v.X*.5,.5,y-v.Y*.5)
	 end,navHandlers)
	 connect(UserInputService.InputEnded,function(inp)
	  if not compactDragging then return end
	  if (compactDragging.UserInputType==Enum.UserInputType.MouseButton1
	   and inp.UserInputType==Enum.UserInputType.MouseButton1)
	    or (compactDragging.UserInputType==Enum.UserInputType.Touch and inp==compactDragging) then
	    compactDragging=nil;compactAnchor=nil;compactOrigin=nil
	  end
	 end,navHandlers)
	 -- Native scrolling content: text and controls must remain usable when the window is short.
	 -- The sidebar/header stay stationary; only the active page can scroll.
	 compactContent=obj('ScrollingFrame',compactMain,{
	  Position=UDim2.fromOffset(143,43),Size=UDim2.fromOffset(451,273),
	  BackgroundTransparency=1,BorderSizePixel=0,ZIndex=13,
	  CanvasSize=UDim2.fromOffset(0,273),CanvasPosition=Vector2.new(0,0),
	  ScrollBarThickness=3,ScrollBarImageColor3=T.glow,
	  ScrollingDirection=Enum.ScrollingDirection.Y,
	  ClipsDescendants=true,
	 })
	 -- A small local status toast for compact: success and error states must not silently disappear.
	 compactToast=frame(compactMain,145,271,449,39,Color3.fromRGB(24,24,24),65,9)
	 edge(compactToast,Color3.fromRGB(154,154,154),1.1,.2)
	 compactToastText=cText(compactToast,'',11,2,427,35,13,T.white,true)
	 compactToastText.TextTruncate=Enum.TextTruncate.AtEnd
	 compactToast.Visible=false
	 local cAccent=frame(compactToast,0,8,3,23,T.primary,66,2);cAccent.Name='FXAccent'
	 -- Chrome is a genuine Roblox UIStroke, not a screenshot. Render on top of all cards.
	 -- Both frames are transparent and non-interactive; they do not cover buttons.
	 local aura=frame(compactMain,5,4,603,314,T.bg,70,13)
	 aura.BackgroundTransparency=1
	 aura.Active=false
	 edge(aura,Color3.fromRGB(122,238,43),5,.80)
	 local chrome=frame(compactMain,6,5,601,312,T.bg,71,13)
	 chrome.BackgroundTransparency=1
	 chrome.Active=false
	 edge(chrome,Color3.fromRGB(168,249,79),2.1,.06)
	 -- V8 tech layer: neon running border, breathing aura, grid, scanline, HUD brackets, veils.
	 local cChrome=FX.strokeOf(chrome)
	 local cAura=FX.strokeOf(aura)
	 FX.neonStroke(cChrome,85)
	 FX.pulse(cAura,'Transparency',.6,.9,3.2)
	 FX.grid(compactMain,143,43,451,273,32,12)
	 FX.brackets(compactMain,6,5,601,312,11,2,72,-4)
	 UI.fxCompact={
	  chrome=cChrome,chromeThick=2.1,aura=cAura,
	  veil=FX.veil(compactMain,6,5,601,312,13,67),
	  pageVeil=FX.veil(compactMain,143,43,451,273,0,14),
	 }
	end
	
	local function showDebug()
	 if UI.compactMode then compactDebug();return end
	 if dialog then dialog:Destroy();dialog=nil end
	 dialog=frame(shell,0,0,W,H,Color3.new(0,0,0),100,0)
	 dialog.BackgroundTransparency=.25
	 local p=panel(dialog,205,112,885,520,21)
	 p.ZIndex=105
	 text(p,'RUM SCRIPT / DEBUG',30,14,725,45,34,T.primary,true,110)
	 local dbg=obj('TextBox',p,{Text=makeReport(),Position=UDim2.fromOffset(26,77),Size=UDim2.fromOffset(834,345),
	  BackgroundColor3=T.bg,TextColor3=T.white,Font=Enum.Font.Code,TextSize=17,
	  TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,
	  TextWrapped=false,TextEditable=true,MultiLine=true,ClearTextOnFocus=false,ZIndex=111})
	 round(dbg,11)
	 interactive(p,'REFRESH',25,440,190,49,function()dbg.Text=makeReport()end)
	 interactive(p,'COPY REPORT',237,440,225,49,function()
	  local cb=type(setclipboard)=='function' and setclipboard or type(toclipboard)=='function' and toclipboard or nil
	  if cb then local ok=pcall(function()cb(makeReport())end)
	    if ok then say('Debug report copied') else say('Copy failed',true)end
	  else dbg:CaptureFocus();say('Select report text manually')end
	 end)
	 interactive(p,'CLOSE',673,440,189,49,function()dialog:Destroy();dialog=nil end)
	end
	UI.showDebug=showDebug
	
	function UI.show(page)
	 currentPage=page
	 -- Entrance motion only when the page actually changes (not when a setting re-renders it).
	 UI.pageChanged=(page~=UI.lastShown) and not UI.booting
	 UI.lastShown=page
	 if UI.compactMode then
	  compactRender(page)
	  if UI.pageChanged then FX.pageIn(compactContent,UI.fxCompact and UI.fxCompact.pageVeil) end
	 else
	  clearPage()
	  paintNav(page)
	  if page=='Player' then playerPage()
	  elseif page=='Settings' then settingsPage()
	  else home() end
	  if content then
	   content.CanvasPosition=Vector2.new(0,0)
	   content.CanvasSize=UDim2.fromOffset(0,page=='Settings' and 1035 or 638)
	  end
	  if UI.pageChanged then FX.pageIn(content,UI.fxWide and UI.fxWide.pageVeil) end
	 end
	 UI.pageChanged=false
	 status('UI',(UI.compactMode and 'Compact ' or 'Native ')..page..' loaded')
	end
	local function startNative()
	 assert(player,'LocalPlayer unavailable')
	 local parent
	 if type(gethui)=='function' then
	  local ok,instance=pcall(gethui)
	  if ok and typeof(instance)=='Instance' then parent=instance end
	 end
	 if not parent then parent=player:WaitForChild('PlayerGui',8) end
	 assert(parent,'PlayerGui unavailable')
	 for _,name in ipairs({'RUMScript_V7','RUMScript_V6','RUMScript_V5','RUMScript_V4','RUMScript_Native'}) do
	  local old=parent:FindFirstChild(name)
	  if old then old:Destroy()end
	 end
	 root=obj('ScreenGui',parent,{Name='RUMScript_Native',IgnoreGuiInset=false,ResetOnSpawn=false,
	   ZIndexBehavior=Enum.ZIndexBehavior.Sibling,DisplayOrder=90})
	 main=frame(root,0,0,W,H,T.bg,1,0)
	 -- No rectangular background outside the rounded shell.
	 main.BackgroundTransparency=1
	 shell=main -- dialogs belong to active GUI, not nil
	 main.AnchorPoint=Vector2.new(.5,.5)
	 main.Position=UDim2.fromScale(.5,.5)
	 main.ClipsDescendants=false
	 scaling=obj('UIScale',main,{Scale=1})
	 -- The approved artwork uses a 29 px shell inset. Keep the surrounding
	 -- 29 px breathing space; do not draw a neon border across the viewport edge.
	 -- No extra outside frame: shellBack, wideAura and wideChrome define the rounded edge.
	 local shellBack=frame(main,29,23,W-58,H-46,T.bg,3,29)
	 -- Border is drawn only by wideChrome (running neon). A static stroke here sat exactly under it and doubled the line.
	 -- Collapsed window = 60%-size RUM Script LOGO (41px vs previous 68px), draggable at top left.
	 mini=obj('ImageButton',root,{
	  Name='RUMScript_Logo_Restore',Image='',
	  Position=UDim2.fromOffset(18+20.5,16+20.5),AnchorPoint=Vector2.new(.5,.5),
	  Size=UDim2.fromOffset(41,41),BackgroundColor3=T.bg,BackgroundTransparency=1,
	  AutoButtonColor=false,BorderSizePixel=0,ZIndex=101,ClipsDescendants=false,
	 })
	 -- Leaf only: no round button, no border, no ring.
	 -- Spring scale for pop-in/out, and a neon light orbiting the logo ring.
	 UI.miniScale=obj('UIScale',mini,{Scale=1})
	 local miniFallback=text(mini,'RS',1,1,39,39,14,T.primary,true,102,Enum.TextXAlignment.Center)
	 UI.miniFallback=miniFallback
	 UI.miniAvatar=obj('ImageLabel',mini,{Name='RUMScriptLogoImage',Image='',
	  Position=UDim2.fromOffset(1,1),Size=UDim2.fromOffset(39,39),
	  BackgroundTransparency=1,ScaleType=Enum.ScaleType.Fit,ZIndex=103})
	 mini.Visible=false
	 -- Drag the icon without accidentally opening the window. Bound to screen edges.
	 local miniDrag=nil
	 local miniStart=nil
	 local miniOrigin=nil
	 local miniMoved=false
	 local miniSuppressUntil=0
	 local function viewportBounds()
	  local cam=workspace.CurrentCamera
	  return cam and cam.ViewportSize or Vector2.new(1280,720)
	 end
	 local function clampMini(x,y)
	  -- Position is the logo centre (AnchorPoint .5,.5).
	  local v=viewportBounds()
	  mini.Position=UDim2.fromOffset(math.clamp(x,20.5,math.max(20.5,v.X-20.5)),
	   math.clamp(y,20.5,math.max(20.5,v.Y-20.5)))
	 end
	 connect(mini.InputBegan,function(inp)
	  if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
	   miniDrag=inp
	   miniStart=inp.Position
	   miniOrigin=mini.Position
	   miniMoved=false
	  end
	 end,navHandlers)
	 connect(UserInputService.InputChanged,function(inp)
	  if not miniDrag or not miniStart then return end
	  if miniDrag.UserInputType==Enum.UserInputType.Touch then
	   if inp~=miniDrag then return end
	  elseif inp.UserInputType~=Enum.UserInputType.MouseMovement then return end
	  local delta=inp.Position-miniStart
	  if math.abs(delta.X)+math.abs(delta.Y)>5 then miniMoved=true end
	  if miniMoved then clampMini(miniOrigin.X.Offset+delta.X,miniOrigin.Y.Offset+delta.Y) end
	 end,navHandlers)
	 connect(UserInputService.InputEnded,function(inp)
	  if not miniDrag then return end
	  local same=(miniDrag.UserInputType==Enum.UserInputType.Touch and inp==miniDrag)
	    or (miniDrag.UserInputType==Enum.UserInputType.MouseButton1
	    and inp.UserInputType==Enum.UserInputType.MouseButton1)
	  if same then
	   if miniMoved then miniSuppressUntil=os.clock()+.30 end
	   miniDrag=nil;miniStart=nil;miniOrigin=nil;miniMoved=false
	  end
	 end,navHandlers)
	 connect(mini.MouseButton1Click,function()
	  if os.clock()<miniSuppressUntil then return end
	  setMinimized(false)
	 end,navHandlers)
	 local function fit()
	  local cam=workspace.CurrentCamera
	  if not cam then return end
	  local v=cam.ViewportSize
	  local insetTop=0
	  local insetBottom=0
	  local ok,cornerTop,cornerBottom=pcall(function() return game:GetService('GuiService'):GetGuiInset() end)
	  if ok and typeof(cornerTop)=='Vector2' and typeof(cornerBottom)=='Vector2' then
	   insetTop=cornerTop.Y
	   insetBottom=cornerBottom.Y
	  end
	  local usableH=math.max(1,v.Y-insetTop-insetBottom)
	  local previous=UI.compactMode
	  UI.compactMode=(v.X<1120 or usableH<660)
	  UI.fit=math.max(.2,math.min(1,(v.X-30)/W,(usableH-30)/H)*.90)
	  local wideMax=math.max(.2,math.min(1.65,(v.X-12)/W,(usableH-12)/H))
	  UI.wideTarget=UI.windowExpanded and wideMax or UI.fit
	  -- While an open/close animation runs, only record the target; the tween owns Scale.
	  if not UI.animating then
	   if UI.smoothNext then tw(scaling,.45,{Scale=UI.wideTarget},Enum.EasingStyle.Back)
	   else scaling.Scale=UI.wideTarget end
	  end
	  applyTextReadability(UI.wideTarget)
	  if compactMain then
	   local compactMax=math.max(.24,math.min(1.65,(v.X-10)/CW,(usableH-10)/CH))
	   local compactNormal=math.max(.24,math.min(1,(v.X-38)/CW,(usableH-38)/CH))
	   UI.compactTarget=UI.windowExpanded and compactMax or compactNormal
	   if not UI.animating then
	    if UI.smoothNext then tw(compactScale,.45,{Scale=UI.compactTarget},Enum.EasingStyle.Back)
	    else compactScale.Scale=UI.compactTarget end
	   end
	   UI.smoothNext=false
	   compactMain.Visible=UI.compactMode and not UI.isMinimized
	   main.Visible=(not UI.compactMode) and not UI.isMinimized
	   if previous~=UI.compactMode then UI.show(currentPage) end
	  end
	 end
	 refreshWindowScale=fit
	 fit()
	 if workspace.CurrentCamera then connect(workspace.CurrentCamera:GetPropertyChangedSignal('ViewportSize'),fit,navHandlers)end
	 assets.logo=loadAsset('logo',LOGO_DATA)
	 assets.chibi=loadAsset('chibi',CHIBI_DATA)
	 assets.leaves='' -- removed from all placements
	 assets.mascot=''
	 assets.swash=''
	 assets.topwave=''
	 assets.bannerwave=''
	 assets.icons=loadAsset('icons',ICONS_DATA)
	 assets.leaf=loadAsset('leaf',LEAF_DATA)
	 -- Collapsed button shows the user's LEAF image (not the logo).
	 if UI.miniAvatar then
	  local av=UI.miniAvatar
	  if assets.leaf~='' then
	   av.Image=assets.leaf
	   av.ImageRectSize=Vector2.new(0,0)
	   av.ImageRectOffset=Vector2.new(0,0)
	   av.ImageColor3=Color3.new(1,1,1)
	   av.Position=UDim2.fromOffset(0,0)
	   av.Size=UDim2.fromOffset(41,41)
	   -- The "RS" text fallback must not show through the leaf's transparent area.
	   if UI.miniFallback then UI.miniFallback.Visible=false end
	  end
	 end
	 -- Effects around the leaf: soft breathing glow, orbiting sparks, gentle float.
	 if UI.miniAvatar and assets.leaf~='' and mini then
	  local holder=obj('Frame',mini,{Name='LeafHolder',BackgroundTransparency=1,Active=false,
	   Position=UDim2.fromOffset(0,0),Size=UDim2.fromOffset(41,41),ZIndex=101})
	  for i,cfg in ipairs({{78,.95},{64,.9},{52,.84}}) do
	   local sz,tr=cfg[1],cfg[2]
	   local g=obj('Frame',holder,{AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromOffset(20.5,20.5),
	    Size=UDim2.fromOffset(sz,sz),BackgroundColor3=T.primary,BackgroundTransparency=tr,
	    BorderSizePixel=0,Active=false,ZIndex=101})
	   round(g,math.ceil(sz/2))
	   FX.pulse(g,'BackgroundTransparency',math.max(.6,tr-.07),math.min(.99,tr+.05),2+i*.45)
	  end
	  UI.miniAvatar.Parent=holder
	  UI.miniAvatar.ZIndex=104
	  for i=1,3 do
	   local size=(i==1) and 5 or 4
	   local d=obj('Frame',holder,{Size=UDim2.fromOffset(size,size),BackgroundColor3=Color3.fromRGB(225,255,190),
	    BorderSizePixel=0,Active=false,ZIndex=105})
	   round(d,3)
	   FX.orbits[d]={speed=(i%2==0) and -1.5 or 1.9,phase=(i-1)*2.094,rx=29+i*1.5,ry=24+i*1.2,size=size}
	   FX.pulse(d,'BackgroundTransparency',0,.7,.9+i*.3)
	  end
	  if not FX.lite then
	   pcall(function()
	    TweenService:Create(holder,TweenInfo.new(1.6,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true),
	     {Position=UDim2.fromOffset(0,-4)}):Play()
	   end)
	  end
	 end
	 assets.dots=loadAsset('dots',DOTS_DATA)
	 runtimeState.imageStatus=assets.logo~='' and 'Embedded logo assigned (render unverified)' or 'Embedded logo unavailable; fallback RS text'
	 status('Artwork', 'Logo URI='..tostring(assets.logo~='')..'; Chibi URI='..tostring(assets.chibi~='')..'; Leaves hidden')
	 navigation()
	 buildCompact()
	 -- The first fit() runs before compactMain exists. Apply it again after creation,
	 -- otherwise compactScale silently stays 1 and may clip under Roblox's top bar.
	 fit()
	 compactMain.Visible=UI.compactMode and not UI.isMinimized
	 main.Visible=(not UI.compactMode) and not UI.isMinimized
	 -- ScrollingFrame (not a plain Frame): the Settings page now grows taller than
	 -- the 638px viewport once Saved Profiles is populated. Home/Player stay the
	 -- same visible size as before; UI.show() sets CanvasSize per page.
	 content=obj('ScrollingFrame',main,{
	  Position=UDim2.fromOffset(300,92),Size=UDim2.fromOffset(953,638),
	  BackgroundColor3=T.bg,BorderSizePixel=0,ZIndex=8,
	  CanvasSize=UDim2.fromOffset(0,638),CanvasPosition=Vector2.new(0,0),
	  ScrollBarThickness=3,ScrollBarImageColor3=T.glow,
	  ScrollingDirection=Enum.ScrollingDirection.Y,
	  ClipsDescendants=true,
	 })
	 content.BackgroundTransparency=1
	 -- Wide-mode border overlay, consistent with compact glow. Click-through transparent frame.
	 local wideAura=frame(main,27,21,W-54,H-42,T.bg,72,30)
	 wideAura.BackgroundTransparency=1
	 wideAura.Active=false
	 edge(wideAura,Color3.fromRGB(121,231,43),5,.82)
	 local wideChrome=frame(main,29,23,W-58,H-46,T.bg,73,29)
	 wideChrome.BackgroundTransparency=1
	 wideChrome.Active=false
	 edge(wideChrome,T.primary,2,.06)
	 toastBox=frame(main,435,654,530,55,Color3.fromRGB(20,20,20),85,14)
	 toastText=text(toastBox,'',18,6,496,44,19,T.white,true,90)
	 toastBox.Visible=false
	 local wAccent=frame(toastBox,0,12,4,31,T.primary,91,2);wAccent.Name='FXAccent'
	 edge(toastBox,Color3.fromRGB(110,110,110),1,.3)
	 -- V8 tech layer for the wide window.
	 local wChrome=FX.strokeOf(wideChrome)
	 local wAura=FX.strokeOf(wideAura)
	 FX.neonStroke(wChrome,60)
	 FX.pulse(wAura,'Transparency',.62,.92,3.4)
	 FX.grid(main,300,92,950,606,48,5)
	 FX.brackets(main,29,23,W-58,H-46,22,3,74,-10)
	 UI.fxWide={
	  chrome=wChrome,chromeThick=2,aura=wAura,
	  veil=FX.veil(main,29,23,W-58,H-46,29,69),
	  pageVeil=FX.veil(main,300,92,953,612,0,9),
	 }
	 FX.startLoop()
	 FX.startTelemetry()
	 UI.booting=true -- page entrance plays when the boot overlay dissolves
	 UI.show('Home')
	 FX.boot()
	 -- Restore saved Anti AFK state on startup, not merely the green toggle.
	 if settings.antiAFK then
	  local armed,why=applyAntiAFK()
	  if not armed then
	   settings.antiAFK=false
	   log('ERROR','Anti AFK','Saved ON could not arm: '..tostring(why))
	  end
	 end
	 if settings.autoReconnect then applyAutoReconnect() end
	 if settings.autoExecute then
	  local armed,why=applyAutoExecute()
	  if not armed then
	   settings.autoExecute=false
	   log('ERROR','Auto Execute','Saved ON could not arm: '..tostring(why))
	  end
	 end
	 -- Named profile auto-load (opt-in, set from Settings -> Saved Profiles).
	 -- Runs after the normal Auto Save load above, so an explicit auto-load
	 -- profile always wins over the plain single-file session save.
	 local autoProfile=getAutoloadSlot()
	 if autoProfile then
	  local okProfile,errProfile=loadConfigSlot(autoProfile)
	  if not okProfile then log('ERROR','Profile','Auto-load failed for "'..autoProfile..'": '..tostring(errProfile)) end
	 end
	 applyToggleKeybind()
	 -- Executor compatibility notice: purely informational, never blocks startup.
	 task.spawn(function()
	  local execName='Unknown'
	  pcall(function() execName=identifyexecutor() or 'Unknown' end)
	  status('Executor','Detected: '..tostring(execName))
	  local low=tostring(execName):lower()
	  if low:find('xeno',1,true) or low:find('solara',1,true) then
	   task.wait(1.4)
	   if aliveUI then say(tostring(execName)..' may not fully support this UI. If something looks off, try another executor.',true) end
	  end
	 end)
	 task.delay(2.5,function()
	  if not aliveUI then return end
	  for _,data in ipairs({{'Logo',UI.compactMode and (UI.compactLogoImage or UI.logoImage) or UI.logoImage},{'Chibi',UI.compactMode and UI.compactChibiImage or UI.mascotImage},
	   {'Collapsed avatar',UI.miniAvatar}}) do
	   local label,element=data[1],data[2]
	   if element and element.Parent then
	    local checked,loaded=pcall(function() return element.IsLoaded end)
	    status('Artwork '..label,checked and ('ImageLabel.IsLoaded='..tostring(loaded)) or 'ImageLabel render status unavailable')
	    if label=='Collapsed avatar' and UI.miniFallback then
	      UI.miniFallback.Visible=(assets.leaf=='') and not (checked and loaded==true)
	    end
	   else
	    status('Artwork '..label,'Image object not created')
	   end
	  end
	 end)
	 local moving=false;local anchor,origin
	 local drag=frame(main,582,7,159,80,T.bg,10,0)
	 drag.BackgroundTransparency=1
	 local trigger=obj('TextButton',drag,{Text='',BackgroundTransparency=1,Size=UDim2.fromScale(1,1),ZIndex=70})
	 connect(trigger.InputBegan,function(inp)
	  if inp.UserInputType==Enum.UserInputType.MouseButton1 then
	   moving=true;anchor=inp.Position;origin=main.Position
	  end
	 end,navHandlers)
	 connect(UserInputService.InputChanged,function(inp)
	  if moving and inp.UserInputType==Enum.UserInputType.MouseMovement then
	   local d=inp.Position-anchor
	   main.Position=UDim2.new(origin.X.Scale,origin.X.Offset+d.X,origin.Y.Scale,origin.Y.Offset+d.Y)
	  end
	 end,navHandlers)
	 connect(UserInputService.InputEnded,function(inp)
	  if inp.UserInputType==Enum.UserInputType.MouseButton1 then moving=false end
	 end,navHandlers)
	 -- Reapply saved local values on respawn; server authority remains unchanged.
	 connect(player.CharacterAdded,function()
	  task.wait(.3)
	  if aliveUI then
	   applyMovement('Respawn');applyNoclip()
	  end
	 end,navHandlers)
	 globalEnv.RUMScriptNative_Close=closeNative
	 print('[RUM Script] Native UI initialized. Artwork APIs: '..tostring(assets.logo~=''))
	end
	local ok,err=guarded('Native UI startup',startNative)
	if not ok then
	 warn('[RUM Script] UI startup failed: '..tostring(err))
	 -- Show the actual error in game, even if the main interface never finishes loading.
	 pcall(function()
	  if root and root.Parent then
	   local failure=Instance.new('TextLabel')
	   failure.Name='RUMScript_Startup_Error'
	   failure.Size=UDim2.fromOffset(540,86)
	   failure.Position=UDim2.new(.5,-270,.5,-43)
	   failure.BackgroundColor3=Color3.fromRGB(16,16,16)
	   failure.TextColor3=Color3.fromRGB(240,95,95)
	   failure.TextWrapped=true
	   failure.TextSize=15
	   failure.Font=Enum.Font.Code
	   failure.Text='RUM Script load error (copy F9 log): '..tostring(err):sub(1,350)
	   failure.ZIndex=100
	   failure.Parent=root
	  end
	 end)
	end
end

return UIModule
